/ {
	aliases {
		hc-sr04 = &hc_sr04_0;
	};

	hc_sr04_0: hc_sr04_sensor {
		compatible = "hc-sr04";
		status = "okay";
		trigger-gpios = <&gpio0 0 GPIO_ACTIVE_HIGH>;
		echo-gpios = <&gpio0 1 GPIO_ACTIVE_HIGH>;
	};
};
